H=["字","读音","类属","取义落点"]
card("台","tái","台：从口㠯聲。口指女陰／男陰之口，㠯聲象性交之狀態，本義為交合、致孕。","引申為孕育、胎兒、後嗣；《集韻》：「嗣，古作台。」又借為三台、臺觀之台。","台上从㠯不从㠯？——台與臺、檯、颱為同音借用，非一字；作「後嗣」義時乃台之本義引申。","本「㠯」聲，㠯為雄性器，故音義相承；今讀 tái，t「涂突」取「突」：交合之突入（推）。","t（今讀 tái）「涂突」取「突」：觸而突入（推）。",[{"title":"①孕育、胎兒、後嗣","note":"","header":H,"rows":[["胎","tāi","肉","胎兒在母腹；取台之致孕義，故从肉"],["始","shǐ","女","女之初、生命之始；取台之孕育義（時點），故从女"],["貽","yí","貝","贈送、遺留；取台之後嗣義，故从貝"],["飴","yí","食","飴糖；取台之甘美滋養義"],["炱","tái","火","煙氣凝黑；台聲記音"],["鮐","tái","魚","鮐魚；台聲記音"]]}])
card("氏","shì","氏：㠯（以）从人，象人俯身之形，本義指父系之族、根柢。","引申為姓氏、宗族；又為「根柢」義。","《說文》：「巴蜀名山岸脅之旁箸欲落墮者曰氏」，乃後起一義，非本義。","本「㠯」聲（氏即㠯从人），與㠯同源。","sh（今讀 shì）「失收」取「收」：收族而聚（推）。",[{"title":"①父系之族、根柢","note":"","header":H,"rows":[["氐","dī","氏下加一","氏下加一，指根部、根本；氏族之根"],["底","dǐ","广","底下、根底；取氏之根柢義"],["低","dī","人","低昂、低下；取氏之根部在下義"],["抵","dǐ","手","抵觸、抵達；取氏之根柢相抵義"],["邸","dǐ","邑","府邸、止舍；取氏之族居義"],["砥","dǐ","石","砥石；取氏之根柢平定義"]]}])
card("氐","dī","氐：从氏下加一，指根部、根本；《說文》「至也」，一本作「本也」。","引申為低、下、根本；又為星名（氐宿）、族名（氐人）。","《說文》析形从氏下箸一，一在地為根，可從；與「氏」所指本同。","本「氏」聲，氏從㠯，故與㠯同源。","d「囤動」取「囤」：根屯於下（推）。",[{"title":"①根部、低下","note":"","header":H,"rows":[["底","dǐ","广","底、下；取氐之根部在下義"],["低","dī","人","低；取氐之在下義"],["抵","dǐ","手","抵；取氐之相抵至義"],["邸","dǐ","邑","邸舍；取氐之止至義"],["砥","dǐ","石","砥；取氐之平定義"]]}])
card("巳","sì","巳：㠯（以）之倒寫，象胎兒之形，本義指胎兒、子嗣。","引申為十二地支第六位；《說文》「巳為蛇，象形」，乃後起分配。","巳與已、㠯古共一字（《正字通》），隸變后分為三形，非三字。","本「㠯」聲，倒寫而音同。","s（今讀 sì）「失收」取「收」：胎收於腹（推）。",[{"title":"①胎兒、子嗣","note":"","header":H,"rows":[["祀","sì","示","祭祀；取巳之嗣續義，故从示"],["汜","sì","水","水決復入、氾濫；巳聲記音"],["姒","sì","女","同父之女；取巳之嗣義"]]}])
card("了","liǎo","了：从子無臂，象嬰兒兩臂尚不能舉，本義指嬰兒、完結。","引申為了結、明白（liǎo）；又為語氣助詞（le）。","《說文》無「了」字，徐鉉新附：「尥也，从子無臂，象形。」","本「子」形之省，非从㠯。","l「拢离」取「离」：事了而離（推）。",[{"title":"①嬰兒、完結","note":"","header":H,"rows":[["尥","liào","尢","行走時足脛相交；取了之屈曲義"],["辽","liáo","辵","遠；了聲記音"]]}])
card("矣","yǐ","矣：从矢以聲，本義為語氣詞，表已然、肯定。","引申為嘆詞；《說文》「語已詞也」。","從矢者，矢為借形，非取矢義；以聲表語氣。","本「以」聲（矣从㠯得聲）。","y為零聲母一系，緒論未列，不系（照實）。",[{"title":"①語氣詞（借形）","note":"","header":H,"rows":[["俟","sì","人","等待；矣聲記音"],["竢","sì","立","等待；矣聲記音"]]}])
card("厶","sī","厶：象雄性器之形，與㠯同源；《正字通》引鄭樵：「厶非自營義；音鳥，男子之勢。」","引申為私自、私下；又為「某」之古字。","厶與㠯、以、氏、巳為一字之異寫，非別字。","本「㠯」聲。","s（今讀 sī）「失收」取「收」：私藏而收（推）。",[{"title":"①私自、雄性之器","note":"","header":H,"rows":[["私","sī","禾","私自、私有；取厶之私義，故从禾"],["厷","gōng","又","肱；厶聲記音"]]}])
